update pages set contenu = '{"sections":[{"type":"heros","h1":"Maintenance mécanique","mecanisme":"Un mécanicien évalué avant d''être envoyé chez vous, qui remonte à la cause de la casse plutôt qu''à la pièce. Il vous laisse un compte rendu écrit, exploitable par votre équipe.","cta":"Demander une intervention","telephone":"04 78 33 72 05","phraseDelai":"Rappel dans l''heure, du lundi au vendredi de 8h00 à 18h30. L''astreinte 24/24 et 7/7 prend le relais la nuit et le week-end."},{"type":"chiffres","chiffres":[{"valeur":"10 %","libelle":"des candidats retenus, après entretien technique ET comportemental"},{"valeur":"+ 100","libelle":"collaborateurs, depuis 4 agences, Lyon (siège), Montréal, Dubaï et Madrid"},{"valeur":"24/24 et 7/7","libelle":"astreinte, pour les sites couverts"}]},{"type":"probleme","punchline":"Un roulement qui siffle depuis trois semaines casse toujours un vendredi soir. Et le vendredi soir, personne n''est disponible.","puces":[{"accroche":"La pièce est changée, la cause reste.","texte":"Même machine, même défaillance, deux mois plus tard. Vous payez trois fois : la pièce, l''arrêt, la récidive."},{"accroche":"Le renfort arrive et ne sait pas faire.","texte":"Un alignement raté, un montage de roulement à froid, et le nouvel organe dure six semaines."},{"accroche":"Personne n''écrit rien.","texte":"Aucun historique de machine, donc chaque intervention repart de zéro et le diagnostic se paie une deuxième fois."},{"accroche":"La casse mécanique n''attend pas.","texte":"Un arbre cassé immobilise la ligne entière, pas un poste."}]},{"type":"offre","lignes":[{"prestation":{"accroche":"La chaîne cinématique complète","texte":"réducteurs, accouplements, courroies, chaînes, pignons, arbres. Remplacement, alignement, reprise de jeu."},"benefice":"Le mouvement se transmet sans perte. Les paliers voisins arrêtent de se détruire les uns après les autres."},{"prestation":{"accroche":"Les roulements traités avant la casse","texte":"montage à chaud, mesure de jeu, analyse vibratoire, échange planifié."},"benefice":"L''arrêt devient une date dans votre planning, pas une surprise un vendredi."},{"prestation":{"accroche":"L''étanchéité tenue","texte":"joints, garnitures mécaniques, presse-étoupe."},"benefice":"Plus de fluide perdu, plus de sol glissant, plus d''accident en attente."},{"prestation":{"accroche":"Le convoyage remis en ligne","texte":"bandes, rouleaux, tapis, élévateurs, tables de transfert."},"benefice":"L''organe qui bloque tout un atelier redevient le premier surveillé."},{"prestation":{"accroche":"Les pompes, vérins et presses révisés","texte":"dépose, expertise, remontage, essais, remise en service."},"benefice":"Un équipement lourd repart avec une cause écrite, pas avec une hypothèse."},{"prestation":{"accroche":"L''ajustage réalisé sur site","texte":"perçage, taraudage, redressage de bâti, changement des pièces d''usure."},"benefice":"Pas d''attente d''atelier extérieur quand la reprise peut se faire chez vous."},{"prestation":{"accroche":"Une expertise mobilisable au-delà de la mécanique","texte":"électricité, automatisme, hydraulique, pneumatique, soudure."},"benefice":"La panne mixte se traite en une visite, pas en deux déplacements."}],"prose":[{"texte":"Besoin d''un mécanicien intégré à votre équipe pour plusieurs mois ? Voir la [sous-traitance maintenance](/offres/residence/). Une casse en cours se traite par le [dépannage industriel](/offres/depannage-industriel/)."}]},{"type":"deroule","etapes":[{"titre":"Vous décrivez la situation","texte":"équipement, bruit, vibration, depuis quand, dans quelles conditions. Quatre champs suffisent, ou un appel au 04 78 33 72 05."},{"titre":"Un technicien vous rappelle dans l''heure","texte":"la panne est qualifiée avec vous, à distance, avant tout déplacement. Vous savez rapidement si nous avons le mécanicien, et lequel."},{"titre":"Le profil est choisi sur la machine","texte":", pas sur une disponibilité. Habilitations, travail en hauteur, espace confiné : les autorisations exigées par votre site sont vérifiées avant l''arrivée."},{"titre":"Le mécanicien intervient en autonomie","texte":"consignation, dépose, expertise, remontage, essais, application de vos consignes et de votre plan de prévention."},{"titre":"La cause racine est cherchée","texte":", pas seulement le symptôme. Balourd, désalignement, graissage inadapté, fixation desserrée : le vrai coupable est nommé."},{"titre":"Vous récupérez un écrit exploitable","texte":"cause identifiée, travaux réalisés, pièces remplacées, préconisations. Le dossier machine s''enrichit à chaque passage."}]},{"type":"garanties","puces":[{"accroche":"Le rappel dans l''heure, du lundi au vendredi de 8h00 à 18h30.","texte":"L''astreinte 24/24 et 7/7 prend le relais en dehors de ces horaires pour les sites couverts."},{"accroche":"Un mécanicien évalué en entretien technique et comportemental.","texte":"Lecture de plan, méthode de dépose, alignement, choix de la bonne pièce, et la rigueur qui va avec. Seuls 10 % des candidats la franchissent."},{"accroche":"Aucune vente de matériel, donc aucun remplacement de confort.","texte":"Nous ne sommes ni fabricant ni distributeur : la pièce proposée est celle qui tient, pas celle qui rapporte."}]},{"type":"cta","question":"Besoin d''un mécanicien qui remonte à la cause plutôt qu''à la pièce ?","bouton":"Demander une intervention","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure."},{"type":"preuves","preuves":[{"titre":"Maintenance d''un parc usinage, pièces mécaniques de précision","texte":"un technicien intégré à temps plein sur les centres d''usinage à grande vitesse, les presses hydrauliques et mécaniques, les machines à commande numérique, depuis 2025","lienLibelle":"Étude de cas VOIT : site du Grand Est","lienHref":"/preuves/voit-grand-est/"},{"titre":"Montage d''un centre logistique, Clermont-Ferrand","texte":"12 monteurs mécaniciens et 8 engins de levage, 6 semaines de chantier en période estivale, livraison tenue","lienLibelle":"Étude de cas AKTID : montage d''un centre logistique","lienHref":"/preuves/aktid-centre-logistique/"},{"titre":"Diagnostic et réparation d''un parc machines défaillant, Lyon","texte":"les machines ont été remises en état sans rachat de matériel neuf, depuis février 2024","lienLibelle":"Étude de cas JOINT LYONNAIS : défaillances machines","lienHref":"/preuves/joint-lyonnais/"},{"titre":"Maintenance préventive et curative d''une fonderie et de son usinage, automobile","texte":"site tenu 7 jours sur 7 depuis octobre 2023, aux côtés des équipes internes","lienLibelle":"Étude de cas STELLANTIS : fonderie de Sept-Fons","lienHref":"/preuves/stellantis-fonderie-sept-fons/"},{"titre":"Montages et déplacements de machines, étanchéité et isolation","texte":"assemblage mécanique et électromécanique de lignes et de sous-ensembles, missions ciblées sur 2025","lienLibelle":"Étude de cas SOPREMA : travaux ponctuels","lienHref":"/preuves/soprema/"}]},{"type":"objections","questions":[{"question":"Combien coûte une intervention mécanique ?","reponse":"Le montant dépend de la casse, de l''accessibilité de l''organe et du niveau d''urgence. Le chiffrage se fait sur devis, déplacement annoncé à l''avance, jamais découvert sur la facture. Un appel de cinq minutes suffit à cadrer le besoin."},{"question":"Nous avons déjà un prestataire mécanique. Comment on bascule ?","reponse":"Nous commençons par un état des lieux du parc, sans jugement sur l''existant : inventaire, points critiques, récupération des historiques disponibles."},{"question":"Qui répond de la sécurité pendant l''intervention ?","reponse":"Vos règles priment sur les nôtres. Plan de prévention signé, accueil sécurité, consignation, habilitations et autorisations vérifiées avant l''arrivée, respect de vos conditions d''accès et de vos clauses de confidentialité."},{"question":"Qui intervient vraiment sur nos machines ?","reponse":"Des mécaniciens salariés de Migen, évalués en entretien technique et comportemental par un homme du métier. 10 % des candidats sont retenus, et l''évaluation continue ensuite sur le terrain : chaque retour client nourrit la fiche du mécanicien."},{"question":"Faites-vous de la mécanique automobile ou agricole ?","reponse":"Non. Notre activité est industrielle : machines de production et utilités. Un véhicule ou un engin agricole relève d''un autre métier et d''un autre atelier. Le dire franchement vous évite une journée perdue."},{"question":"Couvrez-vous notre région, et les petits ateliers ?","reponse":"Oui aux deux. 4 agences, Lyon (siège), Montréal, Dubaï et Madrid, et des hubs de techniciens dans les grandes villes de France partout en France. Un atelier de dix personnes avec deux machines critiques a autant besoin de fiabilité qu''une grande usine."}]},{"type":"ctaFinal","question":"Besoin que la même machine arrête de casser tous les deux mois ?","bouton":"Demander une intervention"}]}'::jsonb where path = '/expertises/mecanique/';
